type AlarmActionInput struct {
	RequestID string `json:"request_id" minLength:"1" maxLength:"200"`
	ExpectedVersion int64 `json:"expected_version" minimum:"0"`
	ExpectedAlarmVersion int64 `json:"expected_alarm_version" minimum:"1"`
	Action string `json:"action" enum:"acknowledge,assign,note,complete,reopen"`
	Reason string `json:"reason" minLength:"1" maxLength:"4000"`
	AssigneeID string `json:"assignee_id,omitempty"`
}

func (s *Business) ActOnAlarm(ctx context.Context,p identity.Principal,id string,input AlarmActionInput)(model.AlarmDetail,error){
	var result model.AlarmDetail
	if err:=businessReason(input.Reason);err!=nil{return result,err}
	alarm,seen,err:=s.alarm(ctx,p,id,"approve");if err!=nil{return result,err}
	c,err:=s.Store.AlarmCase(ctx,alarm);if err!=nil{return result,err}
	scope:="alarm:"+id+":"+p.User.ID;hash:=store.Hash(input)
	actionErr:=s.alarmAction(ctx,p,alarm,c,input.Action)
	err=s.Store.Write(ctx,func(tx *store.Tx)error{
		duplicate,e:=tx.BusinessRequest(scope,input.RequestID,hash,&result);if e!=nil||duplicate{return e}
		if c.Version!=input.ExpectedVersion||alarm.Version!=input.ExpectedAlarmVersion{return store.ErrConflict}
		if actionErr!=nil{return actionErr}
		return nil
	})
	if err!=nil{return result,err};if result.Alarm.ID!=""{return s.AlarmDetail(ctx,p,id)}
	if input.Action=="assign"{if _,err=s.member(ctx,input.AssigneeID,[]string{alarm.EntityID},seen);err!=nil{return result,err}} else if input.AssigneeID!=""{return result,errors.New("assignee_id is only accepted for assign")}
	if err=seen.remember("alarm_case",id,c.Version);err!=nil{return result,err}
	op:=model.AlarmOperation{AlarmID:id,EntityID:alarm.EntityID,DefinitionID:alarm.DefinitionID,Version:1,AlarmVersion:alarm.Version,CaseVersion:c.Version,SourceID:s.NodeID,Action:input.Action,Reason:input.Reason,AssigneeID:input.AssigneeID,Actor:p.Actor,AtMS:s.Store.CurrentTime().UnixMilli(),Basis:[]string{}}
	op.ID="alarm-op:"+store.Hash([]string{s.NodeID,p.User.ID,input.RequestID,id})
	for _,entry:=range c.Operations{op.Basis=append(op.Basis,entry.ID)}
	err=s.Store.Write(ctx,func(tx *store.Tx)error{
		duplicate,e:=tx.BusinessRequest(scope,input.RequestID,hash,&result);if e!=nil||duplicate{return e}
		if e=seen.check(tx);e!=nil{return e}
		op.SourceSequence,e=tx.NextBusinessSequence();if e!=nil{return e}
		updated,e:=tx.ApplyAlarmOperation(op);if e!=nil{return e}
